const PAGINAS={sorteio:{arquivo:"index.min.js",iniciar:"inicializarSorteio",texto:"Preparando o sorteio\u2026"},julgados:{arquivo:"julgados.min.js",iniciar:"inicializarJulgados",texto:"Preparando as pautas\u2026"}},paginaAtual=PAGINAS[document.body.dataset.page],sessionLoading=document.getElementById("sessionLoading");async function carregarPaginaAutenticada(){if(paginaAtual){sessionLoading.hidden=!1,sessionLoading.replaceChildren(criarIndicadorCarregamento(paginaAtual.texto));try{await carregarScript(`assets/js/${paginaAtual.arquivo}?v=${ASSET_VERSION}`),window[paginaAtual.iniciar](),sessionLoading.hidden=!0,sessionLoading.replaceChildren()}catch{const estado=document.createElement("div");estado.className="load-error",estado.setAttribute("role","alert");const texto=document.createElement("p");texto.textContent="N\xE3o foi poss\xEDvel preparar esta p\xE1gina. Verifique sua conex\xE3o e tente novamente.";const tentarNovamente=document.createElement("button");tentarNovamente.type="button",tentarNovamente.className="button-secondary",tentarNovamente.textContent="Tentar novamente",tentarNovamente.addEventListener("click",carregarPaginaAutenticada,{once:!0}),estado.append(texto,tentarNovamente),sessionLoading.replaceChildren(estado)}}}ligarLogin(carregarPaginaAutenticada);
